import ast, pathlib
def nonblank(p):
    return sum(1 for l in pathlib.Path(p).read_text().splitlines() if l.strip())
src = sum(nonblank(p) for p in pathlib.Path("src/gov").rglob("*.py"))
hooks = sum(nonblank(p) for p in pathlib.Path("template/governance/kernel/hooks").rglob("*.py"))
print("src/gov non-blank:", src, " kernel hooks non-blank:", hooks, " total:", src + hooks)
# function sizes (non-blank lines) of the guard's shell-parsing functions
targets = {
 "src/gov/guard/decide.py": None, "src/gov/guard/protected.py": None, "src/gov/guard/heldout.py": None,
 "src/gov/guard/install.py": None, "src/gov/guard/sessionlog.py": None,
}
for f in targets:
    p = pathlib.Path(f)
    if not p.exists():
        print("missing", f); continue
    text = p.read_text()
    lines = text.splitlines()
    tree = ast.parse(text)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef,)):
            body = "\n".join(lines[node.lineno-1:node.end_lineno])
            if "shlex" in body or "split" in node.name or "token" in node.name.lower() or "bash" in node.name.lower() or "operand" in node.name.lower() or "reads" in node.name.lower():
                n = sum(1 for l in lines[node.lineno-1:node.end_lineno] if l.strip())
                print(f"{f}:{node.lineno} {node.name} {n} non-blank; shlex={'shlex' in body}")
EOF
